-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "esMX" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.hunter.ranged.Name"] = "A distancia"
L["rm.era.hunter.ranged.Description"] = "Todos los cazadores del nivel 1 al 60, todos los árboles de talentos. Inicia el combate con Marca del cazador, Disparo de puntería y Disparo automático. En solitario tanquea la mascota: tu propia Picadura de serpiente y después Disparo de puntería, Disparo Arcano y Multidisparo solo mientras tengas más de la mitad del maná, y Disparo de conmoción para kitear antes de tener mascota. En grupo, Disparo de puntería y Multidisparo justo después de un Disparo automático para no retrasarlo nunca, Picadura de serpiente fuera de bandas y Disparo Arcano solo antes de Disparo de puntería o sobre un objetivo a punto de morir. Golpes cuerpo a cuerpo cuando un enemigo está demasiado cerca, instantáneos en movimiento, y Multidisparo y Salva contra tres o más enemigos. Recordatorios: Halcón (antes, Mono), Aura de disparo certero, el cuidado de la mascota, Fuego rápido, Cólera de las bestias y habilidades raciales contra élites y en instancias, Intimidación y Fingir muerte. Las trampas, Cortar alas, Alimentar mascota, Disparo tranquilizante y el posicionamiento quedan a tu cargo."
L["rm.era.hunter.ranged.icyveins.Name"] = "A distancia, recortando disparos automáticos (Icy Veins)"
L["rm.era.hunter.ranged.icyveins.Description"] = "Desactivada por defecto; actívala para un arma a distancia más rápida de 3,0 segundos. Como Cazador: a distancia, pero en grupo Disparo de puntería y Multidisparo salen en cuanto están listos aunque retrasen un Disparo automático, nunca se usa Picadura de serpiente, y Fuego rápido, Cólera de las bestias y las habilidades raciales se usan en cada combate."
L["rm.era.hunter.ranged.simulator.Name"] = "A distancia, Picadura de serpiente en banda (simulador)"
L["rm.era.hunter.ranged.simulator.Description"] = "Desactivada por defecto; actívala donde la banda tenga hueco de perjuicios para tu picadura. Como Cazador: a distancia, pero en grupo Picadura de serpiente se mantiene en todas partes, también en bandas, renovada por debajo de 5 segundos mientras Disparo de puntería y Multidisparo se están recargando, y nunca se usa Disparo Arcano."
L["rm.forever.hunter.ranged.Name"] = "A distancia (Wowhead)"
L["rm.forever.hunter.ranged.Description"] = "Todos los cazadores a distancia del nivel 1 al 60 (Bestias, Puntería y Supervivencia hasta Patada de zancudo), y la opción predeterminada del cazador de Forever. Inicio del combate: Marca del cazador, Disparo de francotirador mientras dure Matanza rápida y Disparo automático. Después tu propio Picadura de serpiente, Invocar halcón dos veces y Disparo Arcano una vez en su tiempo de reutilización compartido (Disparo Arcano cada vez que esté disponible antes de Invocar halcón), Disparo de francotirador con Matanza rápida o contra élites, y Disparo de puntería. Con dos o más enemigos luchando contra ti: Multidisparo en lugar de Disparo de puntería, Trampa explosiva con tres cerca de ti y Salva con cinco. En movimiento: solo disparos instantáneos. Un enemigo cuerpo a cuerpo recibe Golpe de raptor y Mordedura de mangosta. Recordatorios: Aspecto del halcón (el del mono antes de tenerlo), Aura de disparo certero, llamar y revivir a la mascota, Fuego rápido, Cólera de las bestias y Furia sangrienta contra élites o en calabozos, e Intimidación cuando un enemigo te ataca. Las órdenes a la mascota, alimentarla, el kiteo y Fingir muerte quedan a tu cargo; desactiva los recordatorios de mascota si juegas con Lobo solitario. Nunca lee tu maná ni la salud de nadie, que Forever oculta para los addons, así que Marca del cazador y Picadura de serpiente se aplican a cada objetivo y Aliviar mascota queda a tu cargo."
L["rm.forever.hunter.ranged.mobalytics.Name"] = "A distancia, ahorro de maná (Mobalytics)"
L["rm.forever.hunter.ranged.mobalytics.Description"] = "El estilo de subida de nivel con ahorro de maná de Mobalytics, una alternativa a la rotación integrada a distancia de Wowhead recomendada, desactivada de forma predeterminada: actívala y desactiva aquella, o aumenta su prioridad. Mantiene tu Picadura de serpiente, un halcón de Invocar halcón, Disparo de puntería (Multidisparo contra dos o más enemigos), y nunca Disparo Arcano una vez que conoces Invocar halcón; el segundo halcón sobre un objetivo con mucha salud se omite, ya que Forever oculta la salud del objetivo. El mismo inicio de combate, cuerpo a cuerpo, movimiento y recordatorios que la rotación integrada de Wowhead."
L["rm.forever.hunter.survival.Name"] = "Supervivencia cuerpo a cuerpo (Wowhead)"
L["rm.forever.hunter.survival.Description"] = "Supervivencia cuerpo a cuerpo con dos armas una vez que Supervivencia es tu árbol de talentos principal con 21 puntos, el nivel de Patada de zancudo (hasta entonces sube de nivel con la rotación integrada a distancia, como aconsejan las guías). Inicia el combate con Marca del cazador y Picadura de serpiente, y después Mordedura de mangosta, Patada de zancudo, Golpe de raptor y Contraataque, con Trampa explosiva contra tres o más enemigos. Fuera del cuerpo a cuerpo dispara: Picadura de serpiente, Disparo Arcano, Disparo de puntería y Disparo automático. Recordatorios: Aspecto de la bestia, Marca del cazador (Exponer presa la necesita), Fuego rápido y Furia sangrienta contra élites o en calabozos, Disuasión mientras mantienes la atención del objetivo y el cuidado de la mascota (la salud está oculta en Forever, así que Aliviar mascota queda a tu cargo). Un paso opcional de Trampa de inmolación está desactivado por defecto."
L["rm.forever.hunter.survival.weave.Name"] = "Supervivencia a dos manos intercalando (Wowhead)"
L["rm.forever.hunter.survival.weave.Description"] = "El estilo de entrar y salir de Wowhead para un cazador de Supervivencia con arma a dos manos, una alternativa a la rotación integrada de Supervivencia cuerpo a cuerpo recomendada, desactivada de forma predeterminada: actívala y desactiva aquella, o aumenta su prioridad. Cuerpo a cuerpo: Mordedura de mangosta y Golpe de raptor; cuando a Golpe de raptor le faltan más de 2,5 segundos, Patada de zancudo y te alejas. Fuera del cuerpo a cuerpo: Picadura de serpiente, Disparo Arcano, Disparo de puntería y Disparo automático hasta que Golpe de raptor esté casi listo, y vuelves a acercarte. Tú te mueves; RM sigue tu distancia."
L["rm.mop.hunter.beastmastery.Name"] = "Recomendada"
L["rm.mop.hunter.beastmastery.Description"] = "Se elige automáticamente en la especialización Bestias. Abre con Marca del cazador y Matar, y después: Disparo mortal, Matar (retenido un momento cuando Cólera de las bestias está a punto de estar lista), Bandada de cuervos, Carrera de lince, Bestia temible y tu disparo de la sexta fila de talentos si lo tienes, Enfocar Fuego con cinco acumulaciones de Frenesí (o cuatro a punto de desaparecer) pero no durante Cólera de las bestias, Picadura de serpiente sobre objetivos que vayan a sobrevivir, Disparo de cobra para renovarla, Disparo Arcano con 80 de enfoque o durante Cólera de las bestias, y después Disparo de cobra (Disparo firme antes del 81). Con dos o más enemigos luchando contra ti mantiene Tajo de la bestia con Multidisparo, reserva Matar para el enfoque sobrante contra grupos grandes y sugiere Trampa explosiva desde tres. Recordatorios: mascota invocada, revivida y aliviada, Aspecto del halcón o del halcón de hierro, Contradisparo, Fervor, y Cólera de las bestias, Fuego rápido, Estampida y habilidades raciales cuando el combate lo merezca (un élite, una mazmorra o banda, o un objetivo que vaya a sobrevivir). La colocación de trampas, Redirección, Fingir muerte y las defensivas quedan a tu cargo; los recordatorios de Exaltación y Disuasión están desactivados por defecto."
L["rm.mop.hunter.marksmanship.Name"] = "Recomendada"
L["rm.mop.hunter.marksmanship.Description"] = "Se elige automáticamente en la especialización Puntería. Prelanza Disparo de puntería, y después: Disparos firmes de dos en dos para mantener Enfoque firme (desde el 63), Disparo de quimera, Picadura de serpiente sobre objetivos que vayan a sobrevivir, Disparo de puntería siempre que ¡Fuego! lo haga instantáneo, Disparo mortal, tus talentos, y un Disparo de puntería lanzado completo mientras el objetivo esté por encima del 80 % de salud, bajo Fuego rápido o Ansia de sangre, con 85 de enfoque o cuando a Disparo de quimera le falten pocos segundos. Disparo Arcano solo mientras te mueves; si no, Disparo firme. Contra cuatro o más enemigos: Disparo de quimera, Disparo de puntería instantáneo, Multidisparo, Disparo mortal, Trampa explosiva. Los mismos recordatorios que las demás rotaciones integradas de cazador. Si prefieres gastar el enfoque sobrante en Disparo Arcano, usa la variante de Disparo Arcano."
L["rm.mop.hunter.marksmanship.icyveins.Name"] = "Gastar en Disparo Arcano (Icy Veins)"
L["rm.mop.hunter.marksmanship.icyveins.Description"] = "Una alternativa a la rotación integrada de Puntería, tal como la juegan Icy Veins, Method, wowtbc.gg y Hekili: Disparo de puntería solo se lanza completo con el objetivo por encima del 80 % de salud o bajo Fuego rápido o Ansia de sangre, y el enfoque sobrante va en su lugar a Disparo Arcano con 60. Enfoque firme se renueva por debajo de 4 segundos; contra cuatro o más enemigos, Multidisparo va primero. Desactivada por defecto: actívala y desactiva la rotación integrada de Puntería, o súbele la prioridad."
L["rm.mop.hunter.survival.Name"] = "Recomendada"
L["rm.mop.hunter.survival.Description"] = "Se elige automáticamente en la especialización Supervivencia. Abre con Marca del cazador, Flecha negra y Disparo explosivo, y después: Disparo explosivo cada vez que esté disponible y con cada Bloquear y cargar, Disparo mortal, Flecha negra sobre objetivos que vayan a sobrevivir, tus talentos, Picadura de serpiente mantenida con Disparo de cobra, Disparo Arcano con 75 de enfoque, con Emoción de la caza, o con 55 cuando Flecha negra no está por llegar, y después Disparo de cobra (Disparo firme antes del 81). Con dos o más enemigos: primero Multidisparo con Bloquear y cargar y el enfoque lleno, Disparo explosivo hasta cinco objetivos, Disparo mortal, Flecha negra, Trampa explosiva desde tres, y Multidisparo para gastar. Los mismos recordatorios que las demás rotaciones integradas de cazador; las trampas para activar Bloquear y cargar quedan a tu cargo."
L["rm.mop.hunter.unspecialized.Name"] = "Antes de una especialización"
L["rm.mop.hunter.unspecialized.Description"] = "Para los niveles 1 a 9 y cualquier cazador que no haya elegido especialización; las rotaciones integradas de Bestias, Puntería y Supervivencia toman el relevo en cuanto eliges una especialización. Inicia el combate con Marca del cazador y Disparo Arcano, y después Picadura de serpiente sobre objetivos que vayan a sobrevivir, Multidisparo contra tres o más enemigos, Disparo Arcano, Disparo firme y Disparo automático. Te recuerda llamar, revivir y aliviar a tu mascota y mantener Aspecto del halcón."
L["rm.retail.hunter.beastmastery.Name"] = "Asistente de combate de Blizzard"
L["rm.retail.hunter.beastmastery.Description"] = "Recomendada para Bestias. Resalta el próximo hechizo que sugiere el Asistente de combate de Blizzard, el único consejo de rotación que el juego aún permite leer a un addon en el combate de Midnight (invoca a tu mascota por sí mismo); espera mientras lanzas o canalizas. Junto a él, recordatorios de lo que el Asistente de combate deja a tu cargo: Derramamiento de sangre y tu habilidad racial en combate, Contradisparo ante un lanzamiento interrumpible, y Supervivencia del más fuerte siempre que esté disponible en combate. Los lanzamientos enemigos están ocultos en combate, así que la interrupción solo se ilumina donde el juego los muestra; la salud está oculta en Retail, así que decidir cuándo usar tus defensivas (incluidas Exaltación y Aspecto de la tortuga) queda a tu criterio. Los abalorios, Redirección y el cuidado de la mascota quedan a tu cargo."
L["rm.retail.hunter.beastmastery.guide.Name"] = "De referencia (SimulationCraft e Icy Veins)"
L["rm.retail.hunter.beastmastery.guide.Description"] = "Solo de referencia, desactivada por defecto: la prioridad optimizada de Bestias. Las cargas, los tiempos de reutilización y las activaciones están ocultos para los addons en el combate de Midnight, así que no puede funcionar allí; léela o duplícala para experimentar. El Enfoque está oculto en Retail. Invoca a tu mascota y marca al objetivo antes de iniciar el combate. Disparo lacerante justo antes de Cólera de las bestias o antes de llegar al tope de cargas; Cólera de las bestias; Matar con Aullido de líder de la manada o Aliado de la naturaleza, o libremente mientras a Cólera de las bestias le falte mucho; Disparo de cobra con Colmillo de cobra; Disparo de cobra; Disparo lacerante cuando no te alcanza el Enfoque para Disparo de cobra. Forestal oscuro: Flecha negra durante Fuego fulminante y Flecha sollozante cuando termina. Con tres o más enemigos (dos con Tajo de la bestia): Apaleo salvaje para iniciar Tajo de la bestia y, mientras dura, Matar, Disparo lacerante y Disparo de cobra. Recordatorios: Derramamiento de sangre y los recordatorios de utilidad de la rotación integrada del Asistente de combate."
L["rm.retail.hunter.initial.Name"] = "Asistente de combate de Blizzard"
L["rm.retail.hunter.initial.Description"] = "Recomendada antes de elegir una especialización (mientras el juego informa de la especialización inicial del cazador). Resalta el próximo hechizo que sugiere el Asistente de combate de Blizzard, el único consejo de rotación que el juego aún permite leer a un addon en el combate de Midnight; espera mientras lanzas o canalizas. Junto a él, los recordatorios que comparten todas las rotaciones integradas de cazador, cada uno una vez que conoces su hechizo. Cuando elijas una especialización al nivel 10, tomarán el relevo las rotaciones integradas de esa especialización."
L["rm.retail.hunter.marksmanship.Name"] = "Asistente de combate de Blizzard"
L["rm.retail.hunter.marksmanship.Description"] = "Recomendada para Puntería. Resalta el próximo hechizo que sugiere el Asistente de combate de Blizzard, el único consejo de rotación que el juego aún permite leer a un addon en el combate de Midnight; espera mientras lanzas o canalizas. Junto a él, recordatorios de lo que el Asistente de combate deja a tu cargo: Disparo certero y tu habilidad racial en combate, Contradisparo ante un lanzamiento interrumpible, y Supervivencia del más fuerte siempre que esté disponible en combate. Los lanzamientos enemigos están ocultos en combate, así que la interrupción solo se ilumina donde el juego los muestra; la salud está oculta en Retail, así que decidir cuándo usar tus defensivas (incluidas Exaltación y Aspecto de la tortuga) queda a tu criterio."
L["rm.retail.hunter.marksmanship.guide.Name"] = "De referencia (SimulationCraft e Icy Veins)"
L["rm.retail.hunter.marksmanship.guide.Description"] = "Solo de referencia, desactivada por defecto: la prioridad optimizada de Puntería, que gasta Disparos precisos antes del siguiente Disparo de puntería. Las activaciones y las cargas están ocultas en el combate de Midnight, así que no puede funcionar allí; el Enfoque está oculto en Retail, así que se omite el Multidisparo con 70 de Enfoque contra grupos. Marca al objetivo y abre con Disparo de puntería. Centinela: Disparo explosivo, Salva, Disparo certero, Chakram de luz lunar antes de que termine su ventana, Disparo de puntería durante Disparo certero sin Disparos precisos, Fuego rápido, Disparo mortal, Multidisparo (contra dos enemigos con Aspecto de la hidra) o Disparo arcano con Disparos precisos, Disparo de puntería, Chakram de luz lunar, Disparo firme. Forestal oscuro: primero Flecha negra con Disparos precisos, nada de Disparo explosivo durante Bloquear y cargar, Disparo de puntería antes de llegar al tope de cargas, Flecha sollozante. Con tres o más enemigos y Disparos con truco: Disparo explosivo, Salva, Multidisparo para aplicar Disparos con truco, Disparo certero y, mientras dura, Fuego rápido y Disparo de puntería. Usar Disparo certero con 30 acumulaciones de Tiro al blanco o contra un objetivo sin marcar queda a tu cargo."
L["rm.retail.hunter.survival.Name"] = "Asistente de combate de Blizzard"
L["rm.retail.hunter.survival.Description"] = "Recomendada para Supervivencia. Resalta el próximo hechizo que sugiere el Asistente de combate de Blizzard, el único consejo de rotación que el juego aún permite leer a un addon en el combate de Midnight (invoca a tu mascota por sí mismo); espera mientras lanzas o canalizas. Junto a él, recordatorios de lo que el Asistente de combate deja a tu cargo: Derribar y tu habilidad racial en combate, Amordazar ante un lanzamiento interrumpible, y Supervivencia del más fuerte siempre que esté disponible en combate. Los lanzamientos enemigos están ocultos en combate, así que la interrupción solo se ilumina donde el juego los muestra; la salud está oculta en Retail, así que decidir cuándo usar tus defensivas (incluidas Exaltación y Aspecto de la tortuga) queda a tu criterio."
L["rm.retail.hunter.survival.guide.Name"] = "De referencia (SimulationCraft)"
L["rm.retail.hunter.survival.guide.Description"] = "Solo de referencia, desactivada por defecto: la prioridad de Supervivencia de SimulationCraft, en la que Matar genera Punta de la lanza y Derribar, Bocarda, Bomba de fuego salvaje y Golpe de raptor la gastan. Punta de la lanza y las cargas están ocultas en el combate de Midnight, así que no puede funcionar allí. Invoca a tu mascota, marca al objetivo y abre con Bomba de fuego salvaje. Centinela: Matar sin Punta de la lanza, Bocarda, Bomba de fuego salvaje con Marca de centinela, Matar antes de que Derribar esté listo, Derribar, Chakram de luz lunar, Golpe de raptor y, después, Matar, Bomba de fuego salvaje y Derribar. Líder de manada: Matar con Aullido de líder de la manada y, después, Derribar, Bomba de fuego salvaje, Bocarda y Golpe de raptor con Punta de la lanza. Con tres o más enemigos: Bocarda y Bomba de fuego salvaje antes de Derribar, Flagelo de raptor. Recordatorios: Aspecto del águila fuera del cuerpo a cuerpo y los recordatorios de utilidad."
L["rm.sod.hunter.melee.Name"] = "Cuerpo a cuerpo (SoD)"
L["rm.sod.hunter.melee.Description"] = "Elegida en un reino de Temporada de descubrimiento una vez que grabas Golpe lateral, Golpe de dracoleón o Cuchillada, y ni Disparo de quimera ni Disparo explosivo. Mantiene activo el beneficio de Golpe lateral, Mordedura de mangosta con cuatro acumulaciones de Furia de raptor, Golpe de dracoleón con Golpes astutos, Golpe de raptor en cada reinicio, y después Mordedura de mangosta, Golpe de dracoleón, Golpe lateral y Cuchillada; Trampa de inmolación y Cortar alas solo en momentos libres. Cuchillada y Trampa explosiva contra tres o más enemigos; Picadura de serpiente y disparos mientras no alcanzas al objetivo. Recordatorios: Aspecto del halcón (antes del 60, el Aspecto del halcón original), Víbora por debajo del 5 % de maná, el cuidado de la mascota (ninguno con Lobo solitario grabado), Fuego rápido y habilidades raciales una vez acumulado Golpe lateral, Cólera de las bestias. El posicionamiento y las órdenes a la mascota quedan a tu cargo."
L["rm.sod.hunter.ranged.Name"] = "A distancia (SoD)"
L["rm.sod.hunter.ranged.Description"] = "Todos los cazadores a distancia en un reino de Temporada de descubrimiento, del nivel 1 al 60; las runas se usan una vez grabadas. Picadura de serpiente siempre activa y renovada con Disparo de quimera. Con la runa de pantalones Disparo mortal: Multidisparo con cuatro acumulaciones de Disparos con truco, Disparo mortal durante Fuego rápido y sobre objetivos en fase de ejecución, Disparo de quimera, y después Trampa explosiva y Disparo Arcano mientras Multidisparo se recarga. Sin ella: Disparo de quimera, Disparo de puntería con dos acumulaciones de Instrucción de francotirador (sin esa runa, justo después de un Disparo automático), trampas justo antes de que Disparo de quimera esté listo (Trampa de escarcha solo para alimentar Bloquear y cargar), Disparo explosivo, Disparo firme, Multidisparo, Disparo Arcano. Golpes cuerpo a cuerpo cuando un enemigo está demasiado cerca, instantáneos en movimiento, y trampas, Multidisparo y Salva contra tres o más enemigos. Recordatorios: Halcón, Víbora por debajo del 10 % de maná, Corazón del león, Aura de disparo certero, el cuidado de la mascota (ninguno con Lobo solitario grabado), Enfocar fuego con cinco acumulaciones de Frenesí, Fuego rápido, habilidades raciales y Cólera de las bestias contra élites y en instancias. Con Bloquear y cargar grabado, una Trampa de escarcha antes del combate. Intercalar ataques cuerpo a cuerpo y el posicionamiento quedan a tu cargo."
L["rm.tbc.hunter.ranged.simulator.Name"] = "DPS a distancia (simulador)"
L["rm.tbc.hunter.ranged.simulator.Description"] = "Niveles 1–70, todas las especializaciones. Inicia el combate con Marca del cazador, Disparo de puntería y Disparo automático, mantiene activo Disparo automático y usa golpes cuerpo a cuerpo cuando un objetivo te alcanza. Antes de Disparo firme mantiene tu Picadura de serpiente y gasta maná en Disparo de puntería, Multidisparo y Disparo Arcano solo mientras te sobre. Desde el nivel 62: Multidisparo cuando esté listo, Disparo firme justo después de cada Disparo automático, Disparo Arcano para llenar el hueco y Picadura de serpiente en solitario. Con tres o más enemigos luchando contra ti, Multidisparo siempre que esté listo. Te recuerda los aspectos (Víbora cuando escasea el maná, de nuevo Halcón a mitad de maná), el cuidado de la mascota, Matar, los tiempos de reutilización importantes contra élites y jefes, y Disparo silenciador. Las órdenes a la mascota, Redirección, las trampas, Salva, intercalar ataques cuerpo a cuerpo y Fingir muerte quedan a tu cargo."
L["rm.tbc.hunter.ranged.wowhead.Name"] = "DPS a distancia (Wowhead)"
L["rm.tbc.hunter.ranged.wowhead.Description"] = "Niveles 1–70, todas las especializaciones, según los consejos de banda de Wowhead. El mismo inicio de combate, cuerpo a cuerpo, disparos de subida de nivel, Multidisparo contra varios objetivos y recordatorios que la versión de simulador, pero una vez aprendido Disparo firme solo ofrece Multidisparo y Disparo firme después de cada Disparo automático: sin Disparo Arcano de relleno (salvo en movimiento), sin Picadura de serpiente y sin recordatorio de Aspecto de la víbora. Las órdenes a la mascota, Redirección, las trampas, Salva, intercalar ataques cuerpo a cuerpo y Fingir muerte quedan a tu cargo. Una alternativa a la rotación integrada a distancia de simulador recomendada, desactivada de forma predeterminada: actívala y desactiva aquella, o aumenta su prioridad."
